import{_ as a,C as o,o as i,c as n,j as s,a as r,E as l,a2 as h}from"./chunks/framework.sc8Z_ZE3.js";const y=JSON.parse('{"title":"Codex","description":"","frontmatter":{},"headers":[],"relativePath":"install/codex.md","filePath":"install/codex.md"}'),d={name:"install/codex.md"};function c(p,e,g,k,u,m){const t=o("Badge");return i(),n("div",null,[e[0]||(e[0]=s("h1",{id:"codex",tabindex:"-1"},[r("Codex "),s("a",{class:"header-anchor",href:"#codex","aria-label":'Permalink to "Codex"'},"​")],-1)),l(t,{type:"built",text:"Built"}),e[1]||(e[1]=h(` The same launcher runs the OpenAI Codex CLI next to Claude Code, on a developer&#39;s device and on the <a href="/docs/install/runners">server runners</a>. Codex turns run on <code>codex app-server</code>, with only the launcher&#39;s hooks, settings and platform tools.<p>A conformance suite checks that Claude Code and Codex get the same platform decision for the same act; the few differences by design are listed in it.</p><h2 id="you-need" tabindex="-1">You need <a class="header-anchor" href="#you-need" aria-label="Permalink to &quot;You need&quot;">​</a></h2><ul><li>Codex CLI 0.169.0 or newer (<code>npm i -g @openai/codex</code> or <code>brew install codex</code>). Set <code>OCTRYX_CODEX_PATH</code> if it is not on <code>PATH</code>.</li><li>For the governed route: a model added in <strong>Admin › Models</strong> that the Workspace allows. The platform turns LiteLLM&#39;s answers into the events Codex needs. See <a href="/docs/install/models">Models</a>.</li><li>For a seat: your own ChatGPT login, if the Workspace allows Codex seats. Codex never uses a Claude subscription.</li><li>The Workspace must allow Codex: <strong>Workspace settings › Models &amp; agents › Coding tools &amp; devices</strong> (card <strong>Coding engine</strong>). It is allowed by default.</li></ul><h2 id="start-it" tabindex="-1">Start it <a class="header-anchor" href="#start-it" aria-label="Permalink to &quot;Start it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">octryx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--device-auth]       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># your ChatGPT login, for the seat route</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">octryx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--profile </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">governed</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">seat]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--workspace </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NAME]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--model </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ALIAS]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--work-item </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">KEY]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-- </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p>Arguments that would get around the platform are refused, among them <code>-c</code>/<code>--config</code>, <code>--profile</code>/<code>-p</code>, <code>--oss</code> and the sandbox and approval bypass.</p><h2 id="which-engine-runs" tabindex="-1">Which engine runs <a class="header-anchor" href="#which-engine-runs" aria-label="Permalink to &quot;Which engine runs&quot;">​</a></h2><ul><li>The <strong>platform admin</strong> sets the default (<strong>Admin › Models › Defaults</strong>, section <strong>Coding engine</strong>).</li><li>A <strong>Workspace admin</strong> may override it and decides which engines are allowed.</li><li>A <strong>member</strong> chooses among the allowed engines in their profile.</li><li>Workflow runs on a member&#39;s device use that member&#39;s engine. <code>octryx status</code> shows the one that applies to you.</li></ul><h2 id="what-the-platform-keeps-in-control" tabindex="-1">What the platform keeps in control <a class="header-anchor" href="#what-the-platform-keeps-in-control" aria-label="Permalink to &quot;What the platform keeps in control&quot;">​</a></h2><ul><li><strong>Model calls on the governed route</strong> go only through the platform&#39;s gateway, with budget, secret scan, usage, cost and transcript. Codex gets a short-lived platform token; no model key is stored on the machine.</li><li><strong>Model calls on a ChatGPT seat</strong> go through the platform&#39;s seat relay only. The Workspace&#39;s seat policy, content handling, checks, transcript and evidence apply. Codex&#39;s hosted web search is off on the seat. (The seat&#39;s device mode of 0.0.1-alpha, with its loopback proxy, is gone.)</li><li><strong>Tool calls</strong>: every shell command and file edit passes the launcher&#39;s check first, with the Workspace&#39;s deny list and the run&#39;s rules; the check fails closed.</li><li><strong>The hook chain</strong>: a turn starts only when Codex reports exactly the launcher&#39;s three hooks, enabled and trusted by hashes the launcher computes itself. A sandboxed turn starts only when no part of the chain lies in a folder the turn may write, and each round only while the session&#39;s configuration, wrapper and guard are unchanged.</li><li><strong>The repository&#39;s own Codex configuration</strong> cannot change any of this: the work folder is untrusted for Codex, and a turn in which a repository&#39;s <code>.codex/config.toml</code> still takes effect is refused. This fixes <a href="https://github.com/octryx-ai/octryx/security/advisories/GHSA-h4xh-8wqf-rxj4" target="_blank" rel="noreferrer">GHSA-h4xh-8wqf-rxj4</a>.</li><li><strong>Tool shells</strong> get none of the launcher&#39;s own variables except what the turn needs, and no variables whose names contain <code>KEY</code>, <code>SECRET</code> or <code>TOKEN</code>.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Codex 0.169 still runs a tool call when it cannot start the hook, or when the hook&#39;s runner fails or passes its deadline before the guard answers.</li><li>A full-access turn on a person&#39;s own device is no boundary against the agent, as Claude Code&#39;s permission-skipping mode is not. On a server runner the container is the boundary.</li><li>Codex asks for a model catalog in its own format, which the platform does not serve yet; it logs one error and works with default metadata.</li><li>Codex sessions cannot be forked from the phone.</li></ul>`,17))])}const x=a(d,[["render",c]]);export{y as __pageData,x as default};
